function model(p) {
  // A scripted ReAct trace: a support agent resolves a duplicate-charge complaint with five tools.
  // Customer, amounts and IDs are fictional; times are playback seconds, not real latencies.
  const timeout = Math.round(p.billingTool) === 1;   // 0 = Works, 1 = Times out once
  const big = Math.round(p.refundSize) === 1;        // 0 = Under $50, 1 = Over $500
  const showThoughts = Math.round(p.showThoughts) === 0; // labels: 0 = Yes, 1 = No
  const limit = 500;
  const amount = big ? 640 : 42.9;
  const usd = v => '$' + v.toFixed(2);
  const plan = big ? 'Business Fiber 1G' : 'Home Internet 300';
  const tools = [
    { id: 'crm', label: 'CRM lookup', fn: 'crm.lookup', icon: 'contact', detail: 'Finds the customer, account and plan.' },
    { id: 'billing', label: 'Billing history', fn: 'billing.history', icon: 'receipt', detail: 'Lists charges and invoices for a month.' },
    { id: 'policy', label: 'Policy search', fn: 'policy.search', icon: 'book-open', detail: 'Searches the refund policy for the rule that applies.' },
    { id: 'refund', label: 'Refund API', fn: 'refund.create', icon: 'banknote', detail: 'Issues a refund to the card on file. Needs an approval ID above $' + limit + '.' },
    { id: 'case', label: 'Case update', fn: 'case.update', icon: 'clipboard-check', detail: 'Writes the outcome to the support case and closes it.' }
  ];
  const DUR = { thought: 1.2, action: 0.9, observation: 1.1, human: 2.6, final: 2.4 };
  const steps = [];
  let t = 0.8, loop = 0;
  const add = (kind, o) => {
    const dur = o.dur || DUR[kind];
    if (kind === 'thought') loop++;
    steps.push(Object.assign({ i: steps.length, kind, tool: null, call: '', short: '', status: 'ok', retry: false, loop,
      visible: kind !== 'thought' || showThoughts, start: +t.toFixed(2), dur }, o, { dur }));
    t += dur;
  };
  const act = (tool, args, o) => add('action', Object.assign({ tool, call: tools.find(x => x.id === tool).fn + '(' + args + ')', text: 'Calls ' + tools.find(x => x.id === tool).label + '.' }, o || {}));
  const obs = (tool, text, short, o) => add('observation', Object.assign({ tool, text, short }, o || {}));

  add('thought', { text: 'Dana says she was charged twice. First: who is she and what plan is she on?' });
  act('crm', 'name: "Dana Reyes"');
  obs('crm', 'Account ACC-20417, ' + plan + ', ' + usd(amount) + ' a month, in good standing.', 'Found Dana');
  add('thought', { text: 'Check October billing for two identical charges.' });
  act('billing', 'account: "ACC-20417", month: "2026-10"');
  if (timeout) {
    obs('billing', 'Error: no response after 10 seconds (timeout).', 'Timed out', { status: 'error', dur: 1.3 });
    add('thought', { text: 'The billing tool timed out. Retry once; if it fails again, hand the case to a person.' });
    act('billing', 'account: "ACC-20417", month: "2026-10"', { retry: true, text: 'Retries Billing history (attempt 2).' });
  }
  obs('billing', 'Two charges of ' + usd(amount) + ' on Oct 1 for invoice INV-88213. One is a duplicate.', '2 charges');
  add('thought', { text: 'Duplicate confirmed. What does the refund policy allow me to do?' });
  act('policy', 'query: "duplicate charge refund"');
  obs('policy', 'Refund duplicates in full. Agents may refund up to $' + limit + ' alone; above that, a billing supervisor must approve.', 'Limit $' + limit);
  if (big) {
    add('thought', { text: usd(amount) + ' is over the $' + limit + ' limit. I must ask a supervisor and wait before refunding.' });
    add('human', { text: 'Asks Sam Okafor (billing supervisor) to approve a ' + usd(amount) + ' refund. The agent pauses; Sam approves (APR-311).',
      short: 'Approved', call: 'request_approval(amount: ' + usd(amount) + ', reason: "duplicate charge")', status: 'approved' });
  } else {
    add('thought', { text: usd(amount) + ' is under the $' + limit + ' limit, so I can refund it myself.' });
  }
  act('refund', 'account: "ACC-20417", amount: ' + usd(amount) + ', invoice: "INV-88213"' + (big ? ', approval: "APR-311"' : ''));
  obs('refund', 'Refund RF-55102 issued: ' + usd(amount) + ' to the card on file, 3 to 5 business days.', 'Refunded');
  add('thought', { text: 'Refund done. Record it on the case, then reply to Dana.' });
  act('case', 'case: "CS-7781", status: "Resolved"');
  obs('case', 'Case CS-7781 closed as Resolved with the refund reference.', 'Closed');
  const reply = 'Sorry about that, Dana. You were charged ' + usd(amount) + ' twice on Oct 1. I have refunded the extra ' + usd(amount) +
    (big ? ' after a billing supervisor approved it' : '') + ' (ref RF-55102); it reaches your card in 3 to 5 business days.';
  add('final', { text: reply, short: 'Resolved' });

  const actions = steps.filter(s => s.kind === 'action');
  const refunds = actions.filter(s => s.tool === 'refund');
  const counts = {
    toolCalls: actions.length, retries: actions.filter(s => s.retry).length, approvals: steps.filter(s => s.kind === 'human').length,
    thoughts: steps.filter(s => s.kind === 'thought').length, errors: steps.filter(s => s.status === 'error').length, loops: loop
  };
  const duration = +t.toFixed(2);
  return {
    request: 'I was charged twice for my internet this month. Can you fix it?',
    customer: 'Dana Reyes', plan, amount, amountText: usd(amount), limit, needsApproval: amount > limit, showThoughts,
    tools, steps, counts, refundAmount: refunds.length ? amount : 0, refundCount: refunds.length, reply,
    duration, markers: steps.map(s => s.start),
    summary: counts.toolCalls + ' tool calls' + (counts.retries ? ' (1 retry after a timeout)' : '') + ', ' +
      (counts.approvals ? '1 human approval, ' : 'no approval needed, ') + usd(amount) + ' refunded and the case closed.'
  };
}

checkCode:
function check(p) {
  const m = model(p), s = m.steps, timeout = Math.round(p.billingTool) === 1;
  const acts = s.filter(x => x.kind === 'action');
  // 1. Every action is immediately followed by the observation from the same tool.
  const paired = acts.every(a => s[a.i + 1] && s[a.i + 1].kind === 'observation' && s[a.i + 1].tool === a.tool);
  // 2. The refund happens once, after the policy result and, above the limit, after a human approval.
  const refundAt = s.findIndex(x => x.kind === 'action' && x.tool === 'refund');
  const policyAt = s.findIndex(x => x.kind === 'observation' && x.tool === 'policy');
  const humanAt = s.findIndex(x => x.kind === 'human' && x.status === 'approved');
  const gateOk = m.amount > m.limit ? humanAt > policyAt && humanAt < refundAt : humanAt === -1;
  const orderOk = m.refundCount === 1 && policyAt >= 0 && policyAt < refundAt && gateOk;
  // 3. A timeout gets exactly one retry, and the retry is the next tool call after the error.
  const errs = s.filter(x => x.status === 'error');
  const retryOk = timeout
    ? errs.length === 1 && m.counts.retries === 1 && acts.find(a => a.i > errs[0].i).retry === true
    : errs.length === 0 && m.counts.retries === 0;
  // 4. The final reply quotes the refund actually made, and the trace plays in order.
  const fin = s[s.length - 1];
  const replyOk = fin.kind === 'final' && fin.text.includes(m.amountText) && m.refundAmount === m.amount &&
    fin.text.includes('approved') === (m.counts.approvals > 0);
  const timed = s.every((x, k) => k === 0 || x.start > s[k - 1].start) && Math.abs(fin.start + fin.dur - m.duration) < 0.02;
  return {
    pass: paired && orderOk && retryOk && replyOk && timed,
    detail: m.counts.toolCalls + ' tool calls, each followed by its observation; ' + (timeout ? '1 timeout, then exactly 1 retry; ' : 'no timeouts; ') +
      'the ' + m.amountText + ' refund comes after the policy search' + (m.amount > m.limit ? ' and 1 human approval (over the $' + m.limit + ' limit)' : ' with no approval (under $' + m.limit + ')') +
      ', and the final reply quotes ' + m.amountText + '.'
  };
}
